-- +goose Up
-- Single-use password recovery links generated by a superuser. Only the SHA-256 of the token is stored. A link ends in exactly
-- one way: used, revoked, invalidated (the person signed in or opened the app, a newer link replaced it, the account was
-- closed) or, with none of those, expired.
CREATE TABLE password_recovery_links (
    id                 BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id            BIGINT      NOT NULL REFERENCES users (id),
    token_hash         BYTEA       NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    created_by         BIGINT      NOT NULL REFERENCES users (id),
    created_at         TIMESTAMPTZ NOT NULL,
    expires_at         TIMESTAMPTZ NOT NULL CHECK (expires_at > created_at AND expires_at <= created_at + interval '7 days'),
    used_at            TIMESTAMPTZ,
    revoked_at         TIMESTAMPTZ,
    revoked_by         BIGINT      REFERENCES users (id),
    invalidated_at     TIMESTAMPTZ,
    invalidated_reason TEXT        CHECK (invalidated_reason IN ('login', 'access', 'replaced', 'closed')),
    CHECK (num_nonnulls(used_at, revoked_at, invalidated_at) <= 1),
    CHECK ((revoked_at IS NULL) = (revoked_by IS NULL)),
    CHECK ((invalidated_at IS NULL) = (invalidated_reason IS NULL))
);
-- At most one unfinished link per user (an expired one still counts until it is marked); also the tiny index the session query hits.
CREATE UNIQUE INDEX password_recovery_pending_key ON password_recovery_links (user_id)
    WHERE used_at IS NULL AND revoked_at IS NULL AND invalidated_at IS NULL;
CREATE INDEX password_recovery_user_idx ON password_recovery_links (user_id, created_at DESC, id DESC);

-- +goose Down
DROP TABLE password_recovery_links;
